"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[4734],{1416:e=>{e.exports=JSON.parse('{"tag":{"label":"Lakehouse","permalink":"/datagol-knowlegde-base-v1/docs/tags/lakehouse","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":55,"items":[{"id":"Lakehouse/Data sources/About Data sources","title":"About Data sources","description":"Data sources are essentially the points where your raw information is stored. These can range from traditional databases like PostgreSQL and MySQL to modern cloud warehouses such as Snowflake or object storage systems like Amazon S3. The data sources module is designed for simple integration, allowing you to connect to a wide variety of systems, including REST APIs, MongoDB, and other platforms. The connection process is streamlined, using minimal credentials and automatically discovering the structure of your data as soon as you connect. After you are connected, you can perform several key actions to get the most out of your data.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/About Data sources"},{"id":"Lakehouse/About Lakehouse","title":"About Lakehouse","description":"Lakehouse is a hybrid data architecture, which provides a unified platform for storing diverse data (structured, semi-structured, unstructured) and performing advanced analytics. Key capabilities include:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/about-lakehouse"},{"id":"Lakehouse/Orchestrations/About orchestration","title":"About orchestration","description":"Orchestration in DataGOL allows you to define and manage the execution order of multiple pipelines. This is crucial when you have dependencies between pipelines, where one pipeline needs to complete successfully before another can begin. Without orchestration, scheduling pipelines to run independently might lead to failures or unexpected results if a dependent pipeline runs before its required data is ready.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/about-orchestration"},{"id":"Lakehouse/Pipelines/About pipelines","title":"About pipelines","description":"Data pipeline is a structured workflow that facilitates the movement and transformation of data from various data sources into your central warehouse and also in another data source. A pipeline can be compared to a conveyor belt that picks up data, performs specific actions on it, and then deposits it in its designated location.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Pipelines/about-pipelines"},{"id":"Lakehouse/Orchestrations/Adding members to an orchestration","title":"Adding members to an orchestration","description":"You can add users to an orchestration. If they do not already have access to associated pipelines, they can be granted permissions. Only Lakehouse members can be added, and they will receive creator permissions by default.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/adding-members-to-orchestration"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/Amazon Redshift","title":"Amazon Redshift","description":"Adding Amazon Redshift as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/Amazon Redshift"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Amplitude","title":"Amplitude","description":"Adding Amplitude as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Amplitude"},{"id":"Lakehouse/Data sources/Connect Data sources/Data files and storage services/Apify Dataset","title":"Apify Dataset","description":"Adding Apify Dataset as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Data files and storage services/Apify Dataset"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/AppsFlyer","title":"AppsFlyer","description":"Adding AppsFlyer as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/AppsFlyer"},{"id":"Lakehouse/Data sources/Connect Data sources/Data files and storage services/Azure File","title":"Azure File","description":"Adding Azure File as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Data files and storage services/Azure File"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/ChargeBee","title":"ChargeBee","description":"Adding ChargeBee as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/ChargeBee"},{"id":"Lakehouse/Orchestrations/Creating orchestrations","title":"Creating orchestrations","description":"Orchestration in DataGOL allows you to define and manage the execution order of multiple pipelines. This is crucial when you have dependencies between pipelines, where one pipeline needs to complete successfully before another can begin. Without orchestration, scheduling pipelines to run independently might lead to failures or unexpected results if a dependent pipeline runs before its required data is ready.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/creating-orchestration"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Cvent","title":"Cvent","description":"Adding Cvent as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Cvent"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/Databricks","title":"Databricks","description":"Adding Databricks as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/Databricks"},{"id":"Lakehouse/Orchestrations/Deleting an orchestration","title":"Deleting an orchestration","description":"To delete an orchestration, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/deleting-an-orchestration"},{"id":"Lakehouse/Data sources/Designating a partition column","title":"Designating a partition column","description":"To designate a partition column, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/designating-a-partition-column"},{"id":"Lakehouse/Orchestrations/Editing an orchestration","title":"Editing an orchestration","description":"To edit an orchestration, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/editing-an-orchestration"},{"id":"Lakehouse/Data sources/Connect Data sources/Data files and storage services/Folder","title":"Folder","description":"Adding Folder as a data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Data files and storage services/Folder"},{"id":"Lakehouse/Data sources/Generating column metadata catalog with AI","title":"Generating column metadata catalog with AI","description":"To generate the column metadata catalog using AI, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/generating-column-metadata-catalog-with-ai"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/Google BigQuery","title":"Google BigQuery","description":"Adding Google BigQuery data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/Google BigQuery"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/HubSpot","title":"HubSpot","description":"Adding HubSpot as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/HubSpot"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/IBM DB2","title":"IBM DB2","description":"Adding IBM DB2 as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/IBM DB2"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Jira","title":"Jira","description":"Adding Jira as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Jira"},{"id":"Lakehouse/Jobs","title":"Jobs","description":"Navigate to Jobs: Under the Lakehouse section, go to Jobs.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/jobs"},{"id":"Lakehouse/Lakehouse workflow","title":"Lakehouse workflow","description":"1.  Connecting to data Sources: The journey begins with establishing connections to various data sources. Think of these as the starting points where your raw data lives. These could be relational databases like SQL Server, PostgreSQL, cloud data warehouses like Redshift, or even file storage systems such as S3 or Azure blob.. The crucial function here is to enable the Lakehouse to access the data that needs to be processed and analyzed.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/lakehouse-workflow"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Mailchimp","title":"Mailchimp","description":"Adding Mailchimp as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Mailchimp"},{"id":"Lakehouse/Data sources/Managing Data sources","title":"Managing Data sources","description":"-   Data sources can be sorted by creation date, displaying either the latest or oldest entries.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/managing-data-sources"},{"id":"Lakehouse/Orchestrations/Managing orchestrations","title":"Managing orchestrations","description":"You can manage and monitor the orchestrations from the Orchestrations page. The main Orchestration page display a list of all created orchestrations.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/managing-orchestration"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Monday","title":"Monday","description":"Adding Monday as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Monday"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/MongoDB Atlas","title":"MongoDB Atlas","description":"Adding MongoDB Atlas data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/MongoDB Atlas"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/MS SQL","title":"MS SQL","description":"Adding Microsoft SQL Server data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/MS SQL"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/MySQL","title":"MySQL","description":"Adding MySQL data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/MySQL"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/NetSuite","title":"NetSuite","description":"Adding NetSuite as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/NetSuite"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/NetSuite JDBC","title":"NetSuite JDBC","description":"Adding NetSuite-JDBC as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/NetSuite JDBC"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/NetSuite Reporting","title":"NetSuite Reporting","description":"Adding NetSuite Reporting as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/NetSuite Reporting"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Pipedrive","title":"Pipedrive","description":"Adding Pipedrive as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Pipedrive"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/PostgreSQL","title":"PostgreSQL","description":"Adding PostgreSQL data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/PostgreSQL"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Posthog","title":"Posthog","description":"Adding Posthog as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Posthog"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Quickbooks","title":"Quickbooks","description":"Adding Quickbooks as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Quickbooks"},{"id":"Lakehouse/Orchestrations/Running an orchestration","title":"Running an orchestration","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration. The list of created orchestrations is displayed.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/running-an-orchestration"},{"id":"Lakehouse/Data sources/Connect Data sources/Data files and storage services/S3","title":"S3","description":"Adding S3 data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Data files and storage services/S3"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Salesforce","title":"Salesforce","description":"Adding Salesforce as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Salesforce"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/SAP HANA","title":"SAP HANA","description":"Adding SAP HANA as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/SAP HANA"},{"id":"Lakehouse/Schema change detection","title":"Schema change detection","description":"DataGOL\'s Schema Change Detection feature monitors the source tables involved in your pipelines for any modifications to their structure (e.g., new columns, deleted columns, data type changes). This helps you stay informed about potential impacts on your data pipelines and warehouse. When a schema change is detected, it is recorded, indicating the table, the modified columns, and the nature of the change (e.g., data type, size).","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/schema-change-detection"},{"id":"Lakehouse/Data sources/Connect Data sources/Data files and storage services/SFTP Bulk","title":"SFTP Bulk","description":"Adding SFTP Bulk as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Data files and storage services/SFTP Bulk"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Shopify","title":"Shopify","description":"Adding Shopify as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Shopify"},{"id":"Lakehouse/Data sources/Connect Data sources/Databases/Snowflake","title":"Snowflake","description":"Adding Snowflake as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Databases/Snowflake"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Stripe","title":"Stripe","description":"Adding Stripe as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Stripe"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/SurveyMonkey","title":"SurveyMonkey","description":"Adding SurveyMonkey as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/SurveyMonkey"},{"id":"Lakehouse/Orchestrations/Updating the orchestration settings","title":"Updating the orchestration settings","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/updating-the-orchestration-settings"},{"id":"Lakehouse/Orchestrations/Viewing pipeline details of an orchestration","title":"Viewing pipeline details of an orchestration","description":"From the Pipelines tab of an orchestration, you can view the specifics of each pipeline within an orchestration. Click a pipeline link to access its comprehensive details, including its data source and destination. Furthermore, you can find information about the pipeline\'s creator and its designated stage order. For granular insights, the status and job stage details are readily available. To explore the data lineage, scroll right and click the more options icon.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/viewing-pipeline-details-of-an-orchestration"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration graph","title":"Viewing the orchestration graph","description":"The Graphs tab within an orchestration provides a clear visual representation of the pipeline\'s execution order, illustrating the sequence of stages. To view the orchestration graph do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/viewing-the-orchestration-graph"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration run details","title":"Viewing the orchestration run details","description":"The Runs tab provides a comprehensive view of each orchestration execution. Here, you can readily see details such as the run\'s name, the user who initiated it, the start and end times, the total duration, and the current status (e.g., completed, failed). To investigate data lineage, click the more options icon. Additionally, clicking the View Snapshot link offers a detailed, point-in-time overview of that specific run.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/viewing-the-orchestration-run-details"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Xero","title":"Xero","description":"Adding Xero as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Xero"},{"id":"Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Zendesk Support","title":"Zendesk Support","description":"Adding Zendesk Support as data source","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Data sources/Connect Data sources/Business applications and SaaS/Zendesk Support"}],"unlisted":false}}')}}]);